mapper.select:
/* SQL ID : QbnkQstnDAO.qbnkQstnList 설 명 : 문제은행문항목록조회 */
WITH PROF_USER AS ( -- 기준 과목의 담당교수(PROF) 단건 SELECT USER_ID FROM ( SELECT USER_ID, ROW_NUMBER() OVER (ORDER BY SBJCT_ADM_SEQNO ASC) AS RNUM FROM TB_LMS_SBJCT_ADM WHERE SBJCT_ADM_TYCD = 'PROF' AND SBJCT_ID = #{searchKey} ) WHERE RNUM = 1 ), PROF_SBJCT AS ( -- 그 교수가 PROF로 등록된 모든 과목 SELECT SBJCT.SBJCT_ID, PU.USER_ID FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SBJCT_ADM ADM ON ADM.SBJCT_ID = SBJCT.SBJCT_ID AND ADM.SBJCT_ADM_TYCD = 'PROF' JOIN PROF_USER PU ON PU.USER_ID = ADM.USER_ID WHERE SBJCT.DELYN = 'N' AND SBJCT.USEYN = 'Y' ) SELECT A.* , ROW_NUMBER() OVER (ORDER BY A.GRP_QBNK_CTGR_ID DESC, CASE WHEN A.UP_QBNK_CTGR_ID IS NULL THEN 0 ELSE 1 END, A.CTGR_SEQNO) AS LINE_NO , COUNT(A.QBNK_QSTN_ID) OVER() AS TOTAL_CNT FROM ( SELECT QSTN.QBNK_QSTN_ID , CASE WHEN CTGR.UP_QBNK_CTGR_ID IS NULL THEN CTGR.CTGRNM ELSE PARENT.CTGRNM END AS UP_QBNK_CTGRNM , CASE WHEN CTGR.UP_QBNK_CTGR_ID IS NULL THEN '-' ELSE CTGR.CTGRNM END AS CTGRNM , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , USR.USERNM , QSTN.QSTN_TTL , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'QSTN_RSPNS_TYCD' AND CD = QSTN.QSTN_RSPNS_TYCD) AS QSTN_RSPNS_TYNM , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE UP_CD = 'QSTN_DFCTLV_TYCD' AND CD = QSTN.QSTN_DFCTLV_TYCD) AS QSTN_DFCTLV_TYNM , CTGR.CTGR_SEQNO , CTGR.UP_QBNK_CTGR_ID , NVL(CTGR.UP_QBNK_CTGR_ID, CTGR.QBNK_CTGR_ID) AS GRP_QBNK_CTGR_ID -- 상위/하위 분류를 묶어서 정렬하기 위한 그룹핑 키 FROM TB_LMS_QBNK_CTGR CTGR JOIN TB_LMS_QBNK_QSTN QSTN ON CTGR.QBNK_CTGR_ID = QSTN.QBNK_CTGR_ID AND QSTN.DELYN = 'N' JOIN TB_LMS_SBJCT SBJCT ON CTGR.SBJCT_ID = SBJCT.SBJCT_ID AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N' JOIN PROF_SBJCT ADM ON ADM.SBJCT_ID = SBJCT.SBJCT_ID AND ADM.USER_ID = QSTN.USER_ID JOIN TB_LMS_USER USR ON USR.USER_ID = ADM.USER_ID AND USR.USER_ID_STSCD = 'APRV_CMPTN' LEFT JOIN TB_LMS_QBNK_CTGR PARENT -- 상위 카테고리명 조회용 자기조인 ON PARENT.QBNK_CTGR_ID = CTGR.UP_QBNK_CTGR_ID WHERE CTGR.DELYN = 'N'
AND ( CTGR.UP_QBNK_CTGR_ID = #{upQbnkCtgrId} OR CTGR.QBNK_CTGR_ID = #{upQbnkCtgrId} )
AND CTGR.QBNK_CTGR_ID = #{qbnkCtgrId}
AND CTGR.SBJCT_ID = #{sbjctId}
AND CTGR.USER_ID = #{userId}
AND LOWER(QSTN.QSTN_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
) A

mapper.insert:
		/*
             SQL ID : QbnkQstnDAO.qbnkQstnRegist
             설  명 : 문제은행문항등록
         */
        INSERT INTO TB_LMS_QBNK_QSTN (
         	  QBNK_QSTN_ID
			, QBNK_CTGR_ID
			, QSTN_SEQNO
			, USER_ID
			, QSTN_TTL
			, QSTN_CTS
			, QSTN_RSPNS_TYCD
			, QSTN_SCR
			, CRANS_TYCD
			, QSTN_DFCTLV_TYCD
			, RGTR_ID
			, REG_DTTM
         ) VALUES (
         	  #{qbnkQstnId}
			, #{qbnkCtgrId}
			, #{qstnSeqno}
			, #{userId}
			, #{qstnTtl}
			, #{qstnCts}
			, #{qstnRspnsTycd}
			, #{qstnScr}
			, #{cransTycd}
			, #{qstnDfctlvTycd}
			, #{rgtrId}
			, FN_DTTM()
         )

mapper.update:
		/*
             SQL ID : QbnkQstnDAO.qbnkQstnModfiy
             설  명 : 문제은행문항수정
         */
        UPDATE TB_LMS_QBNK_QSTN SET
        	  MDFR_ID   = #{mdfrId}
    		, MOD_DTTM = FN_DTTM()
    		, CRANS_TYCD = #{cransTycd}

    		, QSTN_TTL = #{qstnTtl}


    		, QSTN_CTS = #{qstnCts}


    		, QSTN_RSPNS_TYCD = #{qstnRspnsTycd}


    		, QSTN_DFCTLV_TYCD = #{qstnDfctlvTycd}

    	 WHERE QBNK_QSTN_ID = #{qbnkQstnId}

		/*
             SQL ID : QbnkQstnDAO.qbnkQstnDelynModify
             설  명 : 문제은행문항삭제여부수정
         */
        UPDATE TB_LMS_QBNK_QSTN SET
        	  MDFR_ID = #{mdfrId}
			, MOD_DTTM = FN_DTTM()
			, DELYN = 'Y'
		 WHERE QBNK_QSTN_ID = #{qbnkQstnId}
